for p in sorted(B.glob('batch_*.json')):
    data=json.loads(p.read_text(encoding='utf-8'))
    for r in data:
        changes=updates.get(r['date'],{})
        for k,v in changes.items():
            if k=='url_add':r['url']+='\n'+v
            elif k=='kind':r['status']=r['batch']+' | Reviewed - '+v
            else:r[k]=v
        if 'timing verification' in r['status']:
            r['confidence']='Low'
    p.write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding='utf-8')
print('Second-pass timing checks applied to',len(updates),'rows; unresolved timing confidence capped at Low.')
